// ?Render@MeshClass@@UAEXAAVRenderInfoClass@@@Z
// partial score=0.23 date=2026-09-23
// MeshClass::Render @ 0x0092E4B0 (984 B), vtable 0x00D3C390 slot 12.
// Paste over the stub in Code/Libraries/Source/WWVegas/WW3D2/mesh.cpp.
// Complete body in retail call order; 970 vs 984 B. Remaining: x87 schedule
// of the inlined frustum/AABox cull (retail spills pt.X/pt.Y and consumes
// ext.Z with fsubr; ours keeps them on the FPU stack + fstp st(0), -8 B),
// a 2-byte mov eax,ecx at +0x2b (MatInfo copy), and loop-head padding.
// BFME: emissive-only render filter flag and its zero threshold.
extern unsigned char g_Va0133F42C;
extern float g_01076C24;

// RenderInfoClass::Additional_Pass_Count under its ledger symbol.
class Gen_00923710
{
public:
	int m();
};

// MeshClass::Set_Lighting_Environment under its ledger symbol.
class Gen_0092E440
{
public:
	void bfmeSet(const char *text);
};

// BFME RenderInfoClass delayed material pass list (count at +0x1B0).
class Rva00923770
{
public:
	void * get(int index);
};

void MeshClass::Render(RenderInfoClass & rinfo)
{
	if (g_Va0133F42C) {
		if (Model == NULL || Model->MatInfo == NULL) {
			return;
		}
		VertexMaterialClass * material = Model->MatInfo->Peek_Vertex_Material(0);
		if (material == NULL) {
			return;
		}
		Vector3 emissive;
		material->Get_Emissive(&emissive);
		if (!(emissive.X > g_01076C24 ||
			emissive.Y > g_01076C24 ||
			emissive.Z > g_01076C24)) {
			return;
		}
	}

	if (Is_Not_Hidden_At_All() == false) {
		return;
	}

	// BFME: MeshGeometryClass::SortLevel is witnessed at +0x1C (mesh geometry
	// header still places it after UserText).
	unsigned int sort_level = (unsigned int)*(signed char *)((char *)Model + 0x1c);
	int override_level = *(int *)((char *)this + 0xa0);
	if (override_level < 0 && Container != NULL) {
		override_level = *(int *)((char *)Container + 0xa0);
	}
	if (override_level >= 0) {
		sort_level = override_level;
	}

	if (WW3D::Are_Static_Sort_Lists_Enabled() && sort_level != SORT_LEVEL_NONE) {
		reinterpret_cast<Gen_0092E440 *>(this)->bfmeSet((const char *)rinfo.light_environment);
		m_alphaOverride = rinfo.alphaOverride;
		m_materialPassAlphaOverride = rinfo.materialPassAlphaOverride;
		m_materialPassEmissiveOverride = rinfo.materialPassEmissiveOverride;
		WW3D::Add_To_Static_Sort_List(this, sort_level);
		return;
	}

	const FrustumClass & frustum = rinfo.Camera.Get_Frustum();
	if (!Model->Get_Flag(MeshGeometryClass::SKIN)) {
		const AABoxClass & box = Get_Bounding_Box();
		for (int i = 0; i < 6; i++) {
			const PlaneClass & plane = frustum.Planes[i];
			Vector3 ext;
			ext.X = WWMath::Fast_Is_Float_Positive(plane.N.X) ? box.Extent.X : -box.Extent.X;
			ext.Y = WWMath::Fast_Is_Float_Positive(plane.N.Y) ? box.Extent.Y : -box.Extent.Y;
			ext.Z = WWMath::Fast_Is_Float_Positive(plane.N.Z) ? box.Extent.Z : -box.Extent.Z;
			ext.X = box.Center.X - ext.X;
			ext.Y = box.Center.Y - ext.Y;
			ext.Z = box.Center.Z - ext.Z;
			float delta = ext.Z * plane.N.Z;
			delta = delta + ext.Y * plane.N.Y;
			delta = delta + ext.X * plane.N.X;
			if (delta - plane.D > g_01076C24) {
				return;
			}
		}
	}

	bool rendered_something = false;

	if (Model->PolygonRendererList.Is_Empty()) {
		Model->Register_For_Rendering();
		if (Model->PolygonRendererList.Is_Empty()) {
			return;
		}
	}

	if (sort_level == SORT_LEVEL_NONE) {
		reinterpret_cast<Gen_0092E440 *>(this)->bfmeSet((const char *)rinfo.light_environment);
		m_alphaOverride = rinfo.alphaOverride;
		m_materialPassAlphaOverride = rinfo.materialPassAlphaOverride;
		m_materialPassEmissiveOverride = rinfo.materialPassEmissiveOverride;
	}

	DX8FVFCategoryContainer * fvf_container =
		Model->PolygonRendererList.Peek_Head()->Get_Texture_Category()->Get_Container();
	bool render_base_passes =
		((rinfo.Current_Override_Flags() & RenderInfoClass::RINFO_OVERRIDE_ADDITIONAL_PASSES_ONLY) == 0);
	bool is_alpha =
		(Model->Get_Single_Shader().Get_Alpha_Test() == ShaderClass::ALPHATEST_ENABLE) ||
		(Model->Get_Single_Shader().Get_Src_Blend_Func() == ShaderClass::SRCBLEND_SRC_ALPHA);

	if ((rinfo.Current_Override_Flags() & RenderInfoClass::RINFO_OVERRIDE_SHADOW_RENDERING) &&
		is_alpha == true) {
		render_base_passes = true;
	}

	if (render_base_passes) {
		DX8PolygonRendererListIterator it(&(Model->PolygonRendererList));
		while (!it.Is_Done()) {
			DX8PolygonRendererClass * polygon_renderer = it.Peek_Obj();
			polygon_renderer->Get_Texture_Category()->Add_Render_Task(polygon_renderer, this);
			it.Next();
		}
		rendered_something = true;
	}

	for (int i = 0; i < reinterpret_cast<Gen_00923710 *>(&rinfo)->m(); i++) {
		MaterialPassClass * matpass = rinfo.Peek_Additional_Pass(i);
		if ((!Is_Alpha()) || matpass->Is_Enabled_On_Translucent_Meshes()) {
			if (rinfo.Current_Override_Flags() & RenderInfoClass::RINFO_OVERRIDE_ADDITIONAL_PASSES_ONLY) {
				fvf_container->Add_Delayed_Visible_Material_Pass(matpass, this);
			} else {
				fvf_container->Add_Visible_Material_Pass(matpass, this);
			}
			rendered_something = true;
		}
	}

	for (int j = 0; j < *(int *)((char *)&rinfo + 0x1b0); j++) {
		MaterialPassClass * matpass = static_cast<MaterialPassClass *>(
			reinterpret_cast<Rva00923770 *>(&rinfo)->get(j));
		if (matpass != NULL &&
			((!Is_Alpha()) || matpass->Is_Enabled_On_Translucent_Meshes())) {
			static_cast<DX8RigidFVFCategoryContainer *>(fvf_container)
				->DX8RigidFVFCategoryContainer::Add_Delayed_Visible_Material_Pass(matpass, this);
			rendered_something = true;
		}
	}

	if (rendered_something && Model->Get_Flag(MeshGeometryClass::SKIN)) {
		static_cast<DX8SkinFVFCategoryContainer *>(fvf_container)->Add_Visible_Skin(this);
	}
}
